{
  "case_id": "xsu_sg_006_work_history_information",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret nævner ikke, at oplysninger om arbejdstimer og indkomst indhentes fra Skattestyrelsen. Det nævner heller ikke, at ansøgerens egne oplysninger om tidligere arbejdsforhold inddrages, eller at arbejde før ansøgningen kan indgå, navnlig ved ophør af andre årsager uden forværring. Det tilføjer desuden retsregler fra afgørelser, som den officielle vejledning ikke støtter: det reducerede fribeløb, 'ikke uvæsentligt omfang', og at studierelevans, geografi og specialpædagogisk støtte ikke indgår. Svaret indrømmer selv, at kilderne ikke handler direkte om Udbetaling Danmark."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Tre af de fire kritiske elementer mangler: Skattestyrelsen som kilde til arbejdstimer og indkomst, ansøgerens egne oplysninger om tidligere arbejdsforhold og arbejde før ansøgningen (navnlig ved ophør af andre årsager uden forværring). Kun 'arbejde ved siden af studiet' er delvist dækket."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret handler om, hvad myndigheden vægter i afgørelser, f.eks. fribeløb og studiejob. Det besvarer ikke, hvilke oplysninger Udbetaling Danmark indhenter og inddrager, nemlig Skattestyrelsens data og ansøgerens egne oplysninger. Det omformulerer spørgsmålet til en anden myndighed og andre afgørelser."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret angiver identificerbare kilder: fem afgørelser fra Ankenævnet for SU med journalnumre og KEN-numre, og de er knyttet til udsagnene med henvisninger."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "De angivne kilder er ældre ankenævnsafgørelser fra 2013-2015. De er ikke den aktuelle vejledning (VEJ 2026, afsnit 3.4.1.3) eller de aktuelle bestemmelser i den frosne kildeafgrænsning. Svaret siger selv, at de ikke direkte handler om Udbetaling Danmark."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De angivne afgørelser understøtter ikke kerneudsagnet om, hvilke oplysninger Udbetaling Danmark indhenter og inddrager. Passagerne i den frosne kilde, som ville understøtte det, er ikke citeret. Påstande som det reducerede fribeløb og at specialpædagogisk støtte ikke indgår kan ikke verificeres mod det frosne materiale."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer ting, som det frosne materiale ikke understøtter: det reducerede fribeløb som moment, vurdering af studiejob i mindre omfang med skånehensyn, at studierelevans og geografi ikke tillægges vægt, og at specialpædagogisk støtte og øget tidsforbrug ikke indgår."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Den krævede kvalifikation mangler: de nævnte omstændigheder ved tidligere arbejde er særligt relevante situationer, ikke udtømmende, og oplysningerne afgør ikke alene retten. Svaret siger heller ikke, at oplysningerne indgår i en samlet vurdering uden automatisk afslag. Dog er nogle formuleringer forsigtige ('kan være et moment')."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: det beskriver, hvad afgørelserne lægger vægt på, og at de handler om SU-styrelsen og ankenævnet. Konklusionerne følger af de beskrevne afgørelser, selv om de er utilstrækkelige i forhold til spørgsmålet."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gengiver ikke modaliteten fra kilden, hvor Udbetaling Danmark 'indhenter' og 'inddrager' oplysninger, mens arbejde før ansøgningen 'kan indgå'. Det bruger i stedet 'typisk' og 'især' og tilskriver en generel afgørelsespraksis som en regel. Udsagnet om, hvad der 'ikke indgår', fremstår mere absolut, end kilden understøtter."
    }
  },
  "xhaile_coverage": {
    "A18": {
      "label": "no",
      "reason": "Svaret nævner ikke, at oplysninger om arbejdstimer og indkomst indhentes fra Skattestyrelsen."
    },
    "A19": {
      "label": "no",
      "reason": "Svaret nævner ikke, at ansøgerens egne oplysninger om tidligere arbejdsforhold fra ansøgningen inddrages."
    },
    "A20": {
      "label": "partial",
      "reason": "Svaret nævner arbejde ved siden af studiet, hvilket svarer til erhvervsarbejde under studiet. Det dækker ikke arbejde før ansøgningen, ophør af andre årsager eller manglende forværring."
    }
  },
  "overall_notes": "Svaret bygger på ældre ankenævnsafgørelser i stedet for den aktuelle vejledning og udelader de centrale elementer: Skattestyrelsens oplysninger, ansøgerens egne oplysninger om tidligere arbejde og arbejde før ansøgningen. Det tilføjer ikke-understøttede regler og angiver kilder, som ikke er aktuelle. Kildehenvisningerne er identificerbare, så C04 er opfyldt."
}

